def should_retry(status, error):
    # Retry status 429 and all 5xx; never retry other 4xx
    # When status is None, retry only error values 'timeout' or 'connection'
    # Unknown errors must be False
    if status is None:
        if error in ('timeout', 'connection'):
            return True
        else:
            return False
    # status is not None
    if isinstance(status, int):
        if status == 429:
            return True
        if 500 <= status <= 599:
            return True
        if 400 <= status <= 499:
            # never retry other 4xx (i.e., exclude 429 which is 429)
            # but 429 already handled, and 4xx other than 429 should be False
            # 4xx range includes 400-499, so return False for all
            return False
        # any other status (e.g., 1xx, 2xx, 3xx) -> False
        return False
    # status might be something else; default False
    return False
